const steps=[[1,0],[0,1],[-1,1],[-1,0],[0,-1],[1,-1]];
export const TILE_CHOICES=[['city','Retro City'],['ranch','Ranch'],['paddock','Paddock'],['sugar-shack','Sugar shack'],['crop','Garden'],['meadow','Meadow'],['moon','Moonbase']];
export function axial(center,diameter){const r=center.z/(diameter*.75);return {q:Math.round(center.x/(Math.sqrt(3)*diameter/2)-r/2),r:Math.round(r)};}
export function tileCenter(q,r,diameter){return {x:Math.sqrt(3)*diameter/2*(q+r/2),z:diameter*.75*r};}
export function extendTiles(base,extras,diameter){const result=base.map(t=>({...t})),occupied=new Set(base.map(t=>{const c=axial(t.center,diameter);return c.q+','+c.r;}));for(const e of extras){if(!Number.isInteger(e.q)||!Number.isInteger(e.r)||!TILE_CHOICES.some(([id])=>id===e.type))continue;let cell={q:e.q,r:e.r};if(occupied.has(cell.q+','+cell.r))cell=frontier(result,diameter)[0];if(!cell)continue;occupied.add(cell.q+','+cell.r);result.push({id:e.id,type:e.type,center:tileCenter(cell.q,cell.r,diameter),seed:e.seed,rotation:0,...(e.placement?{placement:{...e.placement}}:{}),...(e.garden?{garden:{...e.garden}}:{})});}return result;}
export function frontier(tiles,diameter){const cells=tiles.map(t=>axial(t.center,diameter)),occupied=new Set(cells.map(c=>c.q+','+c.r)),out=new Map();for(const c of cells)for(const [dq,dr]of steps){const q=c.q+dq,r=c.r+dr,k=q+','+r;if(!occupied.has(k))out.set(k,{q,r});}return [...out.values()].sort((a,b)=>Math.atan2(a.r,a.q)-Math.atan2(b.r,b.q)||a.q-b.q||a.r-b.r);}

export const SCENE_GENERATORS=[{id:'ranch',label:'Ranch',tiles:['ranch','paddock','sugar-shack']},{id:'city',label:'Retro City',tiles:['city']},{id:'garden',label:'Garden',tiles:['crop']},{id:'meadow',label:'Meadow',tiles:['meadow']},{id:'moon',label:'Moonbase',tiles:['moon']}];
// Compatibility export: shared scene picker, approved diorama icon.
export function multiHexIcon(){return "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 48 42\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" data-asset-id=\"ui.scene-picker.diorama\"><path d=\"M8 23 3 26 24 37 45 26 38 22M3 26v5l21 10 21-10v-5M24 37v4\"/><path d=\"M9 26V15l6-7 6 12v12L9 26ZM15 8l8-4 7 12-9 4M30 16v11l-9 5M13 28v-7l4 2v7\"/><path d=\"M36 25V14m0 5-3-3m3 1 3-3M31 17c-5-1-5-7-1-8-1-5 7-7 9-2 5 0 7 7 3 9-1 3-4 4-6 2-2 2-4 1-5-1Z\"/></svg>";}
